// AP Physics 1 review, Unit 2 (part a): topics 2.1 to 2.5 (systems and center of mass, forces and free-body diagrams,
// Newton's third, first, and second laws). Multiple choice with a free-response MR and TBR.
import { graph } from "../../plot.js";
import { scene, fbd, incline, atwood, tablePulley } from "../../diagrams.js";

// ---- drawing helpers (each builds a scene() description) ----
const line4 = (x, y, w, h) => [
  { line: { from: [x, y], to: [x + w, y] } }, { line: { from: [x + w, y], to: [x + w, y + h] } },
  { line: { from: [x + w, y + h], to: [x, y + h] } }, { line: { from: [x, y + h], to: [x, y] } },
];
// four labeled panels in a 2 by 2 grid; each panel is { letter, items(ox, oy) } with the panel's lower left corner as origin
const panels4 = (alt, list, pw = 210, ph = 150) => {
  const items = [];
  list.forEach((p, i) => {
    const ox = 10 + (i % 2) * (pw + 10), oy = 10 + (i < 2 ? ph + 10 : 0);
    items.push(...line4(ox, oy, pw, ph), { label: { x: ox + 14, y: oy + ph - 16, text: p.letter } }, ...p.items(ox, oy));
  });
  return scene({ width: 2 * pw + 30, height: 2 * ph + 30, alt, items });
};
const arrowAt = (x, y, angle, len, label, kind = "force") => {
  const r = (angle * Math.PI) / 180;
  return { arrow: { from: [x, y], to: [x + len * Math.cos(r), y + len * Math.sin(r)], label, kind } };
};

// ---- 2.1 ----
const rodDiagram = (alt) => {
  const x0 = 40, x1 = 400, sx = (d) => x0 + (d / 100) * (x1 - x0), items = [{ rect: { x: (x0 + x1) / 2, y: 120, w: x1 - x0, h: 10 } }, { line: { from: [x0, 50], to: [x1, 50] } }];
  for (let d = 0; d <= 100; d += 10) items.push({ line: { from: [sx(d), 50], to: [sx(d), 57] } }, { label: { x: sx(d), y: 36, text: String(d) } });
  items.push({ label: { x: x1 + 22, y: 36, text: "cm", anchor: "start" } });
  for (const [at, m] of [[10, "2.0 kg"], [40, "1.0 kg"], [90, "3.0 kg"]]) items.push({ rect: { x: sx(at), y: 97, w: 44, h: 30, label: m } });
  return scene({ width: 470, height: 160, alt, items });
};
